add_action('init', function(){
 if(!taxonomy_exists('pa_brand')){
  register_taxonomy('pa_brand',['product'],[
   'label'=>'برند','public'=>true,'show_ui'=>true,'hierarchical'=>false,
   'rewrite'=>['slug'=>'brand'],'show_admin_column'=>true,
  ]);
 }
});

class Baharaan_Commerce {
