/** Privacy-hardened lead endpoint used by the public chat wrapper. */
function bhc_privacy_key(){return hash('sha256',wp_salt('auth').'|bhc-privacy');}
function bhc_privacy_encrypt($value){if($value==='')return '';if(!function_exists('openssl_encrypt'))return '';$key=substr(hash('sha256',bhc_privacy_key(),true),0,32);$iv=random_bytes(16);$raw=openssl_encrypt($value,'AES-256-CBC',$key,OPENSSL_RAW_DATA,$iv);return $raw===false?'':base64_encode($iv.$raw);}
function bhc_privacy_decrypt($value){if($value===''||!function_exists('openssl_decrypt'))return '';$bin=base64_decode((string)$value,true);if($bin===false||strlen($bin)<17)return '';$key=substr(hash('sha256',bhc_privacy_key(),true),0,32);$plain=openssl_decrypt(substr($bin,16),'AES-256-CBC',$key,OPENSSL_RAW_DATA,substr($bin,0,16));return $plain===false?'':(string)$plain;}
function bhc_privacy_mask($value){$value=(string)$value;if($value==='')return 'ثبت نشده';if(strpos($value,'@')!==false){[$a,$b]=array_pad(explode('@',$value,2),2,'');return mb_substr($a,0,1,'UTF-8').'***@'.$b;}return mb_substr($value,0,3,'UTF-8').'***'.mb_substr($value,-2,2,'UTF-8');}
function bhc_rate_subject($prefix){
 $ip=sanitize_text_field($_SERVER['REMOTE_ADDR']??'unknown');
 $ua=sanitize_text_field($_SERVER['HTTP_USER_AGENT']??'unknown');
 $uid=(int)get_current_user_id();
 return $prefix.hash('sha256',$uid.'|'.$ip.'|'.$ua);
}
function bhc_secure_lead(){
 if(('POST'!==($_SERVER['REQUEST_METHOD']??''))) wp_send_json_error(['message'=>'روش درخواست نامعتبر است.'],405);
 check_ajax_referer('bhc_nonce','nonce');
 $msg=sanitize_textarea_field(wp_unslash($_POST['message']??''));
 $name=sanitize_text_field(wp_unslash($_POST['name']??''));
 $contact=sanitize_text_field(wp_unslash($_POST['contact']??''));
 $consent=!empty($_POST['contact_consent']);
 if(!$msg||mb_strlen($msg,'UTF-8')>1500) wp_send_json_error(['message'=>'متن پیام معتبر نیست.'],400);
 if($contact!==''&&!$consent) wp_send_json_error(['message'=>'برای ذخیره راه تماس، رضایت خود را فعال کنید.'],400);
 if(preg_match('/(?:cvv|cvc|otp|رمز|رمز پویا|کد یک.?بارمصرف|شماره کارت|password|passcode)/iu',$msg.' '.$contact)) wp_send_json_error(['message'=>'لطفاً اطلاعات بانکی، رمز یا کد یک‌بارمصرف ارسال نکنید.'],400);
 $ip=sanitize_text_field($_SERVER['REMOTE_ADDR']??'unknown');
 $rate=bhc_rate_subject('bhc_secure_lead_');$used=(int)get_transient($rate);
 if($used>=8)wp_send_json_error(['message'=>'درخواست‌های زیادی ثبت شده است؛ کمی بعد تلاش کنید.'],429);
 set_transient($rate,$used+1,5*MINUTE_IN_SECONDS);
 $id=wp_insert_post(['post_type'=>'bhc_lead','post_status'=>'private','post_title'=>($name?:'مهمان').' — '.current_time('mysql'),'post_content'=>$msg],true);
 if(is_wp_error($id)||!$id)wp_send_json_error(['message'=>'ثبت پیام انجام نشد.'],500);
 $privacy_token=wp_generate_password(32,false,false);
 update_post_meta($id,'_bhc_contact',bhc_privacy_mask($contact));
 update_post_meta($id,'_bhc_contact_enc',bhc_privacy_encrypt($contact));
 update_post_meta($id,'_bhc_privacy_token_hash',hash('sha256',$privacy_token));
 update_post_meta($id,'_bhc_contact_consent',$contact!==''?'1':'0');
 update_post_meta($id,'_bhc_stage','new');$cid=sanitize_text_field(wp_unslash($_POST['conversation_id']??''));if(preg_match('/^[a-f0-9]{32}$/',$cid))update_post_meta($id,'_bhc_conversation',$cid);
 update_post_meta($id,'_bhc_privacy_expires',time()+90*DAY_IN_SECONDS);
 update_post_meta($id,'_bhc_page',esc_url_raw(wp_get_referer()?:''));
 $ticket='BH-'.strtoupper(substr(hash('sha256',$id.'|'.wp_salt('auth')),0,8));update_post_meta($id,'_bhc_ticket',$ticket);wp_send_json_success(['message'=>'پیامتان ثبت شد. شماره پیگیری '.$ticket.' است.','privacy_token'=>$privacy_token,'ticket'=>$ticket]);
}
add_action('wp_ajax_bhc_lead_secure','bhc_secure_lead');
add_action('wp_ajax_nopriv_bhc_lead_secure','bhc_secure_lead');

function bhc_privacy_delete(){
 if(('POST'!==($_SERVER['REQUEST_METHOD']??'')))wp_send_json_error(['message'=>'روش درخواست نامعتبر است.'],405);
 check_ajax_referer('bhc_nonce','nonce');
 $token=sanitize_text_field(wp_unslash($_POST['privacy_token']??''));
 if($token===''||strlen($token)<20)wp_send_json_error(['message'=>'توکن حذف معتبر نیست.'],400);
 $ids=get_posts(['post_type'=>'bhc_lead','post_status'=>'private','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_bhc_privacy_token_hash','meta_value'=>hash('sha256',$token)]);
 if(!$ids)wp_send_json_error(['message'=>'درخواست منطبق پیدا نشد.'],404);
 wp_delete_post((int)$ids[0],true);
 wp_send_json_success(['message'=>'داده درخواست و راه تماس حذف شد.']);
}
add_action('wp_ajax_bhc_privacy_delete','bhc_privacy_delete');
 add_action('wp_ajax_nopriv_bhc_privacy_delete','bhc_privacy_delete');

function bhc_privacy_export(){
 if(('POST'!==($_SERVER['REQUEST_METHOD']??'')))wp_send_json_error(['message'=>'روش درخواست نامعتبر است.'],405);
 check_ajax_referer('bhc_nonce','nonce');
 $token=sanitize_text_field(wp_unslash($_POST['privacy_token']??''));
 if($token===''||strlen($token)<20)wp_send_json_error(['message'=>'توکن export معتبر نیست.'],400);
 $ids=get_posts(['post_type'=>'bhc_lead','post_status'=>'private','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_bhc_privacy_token_hash','meta_value'=>hash('sha256',$token)]);
 if(!$ids)wp_send_json_error(['message'=>'درخواست منطبق پیدا نشد.'],404);
 $id=(int)$ids[0];$post=get_post($id);$enc=get_post_meta($id,'_bhc_contact_enc',true);
 wp_send_json_success(['data'=>['request_id'=>$id,'message'=>wp_strip_all_tags((string)$post->post_content),'contact'=>bhc_privacy_decrypt($enc),'created'=>$post->post_date,'stage'=>sanitize_key(get_post_meta($id,'_bhc_stage',true)?:'new')]]);
}
add_action('wp_ajax_bhc_privacy_export','bhc_privacy_export');
add_action('wp_ajax_nopriv_bhc_privacy_export','bhc_privacy_export');

function bhc_order_lookup(){
 if(('POST'!==($_SERVER['REQUEST_METHOD']??'')))wp_send_json_error(['message'=>'روش درخواست نامعتبر است.'],405);
 check_ajax_referer('bhc_nonce','nonce');
 $rate=bhc_rate_subject('bhc_order_lookup_');$used=(int)get_transient($rate);
 if($used>=8)wp_send_json_error(['message'=>'تعداد درخواست‌ها زیاد است؛ کمی بعد دوباره تلاش کنید.'],429);
 set_transient($rate,$used+1,10*MINUTE_IN_SECONDS);
 $order_id=absint($_POST['order_id']??0);$email=sanitize_email(wp_unslash($_POST['email']??''));
 if(!$order_id||!function_exists('wc_get_order'))wp_send_json_error(['message'=>'شماره سفارش معتبر نیست.'],400);
 $order=$order_id?wc_get_order($order_id):false;
 $uid=get_current_user_id();$authorized=$order&&$uid>0&&((int)$order->get_user_id()===$uid);
 if($order&&!$authorized&&$email!=='')$authorized=hash_equals(strtolower((string)$order->get_billing_email()),strtolower($email));
 if(!$order||!$authorized)wp_send_json_error(['message'=>'سفارش با این اطلاعات پیدا نشد.'],404);
 $status=$order->get_status();$labels=['pending'=>'در انتظار پرداخت','processing'=>'در حال آماده‌سازی','on-hold'=>'در انتظار تأیید پرداخت','completed'=>'تکمیل‌شده','cancelled'=>'لغوشده','refunded'=>'مستردشده','failed'=>'پرداخت ناموفق','draft'=>'پیش‌نویس'];
 $lines=[];foreach($order->get_items() as $item){if(!is_object($item)||!method_exists($item,'get_name'))continue;$lines[]=['name'=>sanitize_text_field($item->get_name()),'qty'=>(int)$item->get_quantity()];if(count($lines)>=8)break;}
 $tracking='';$eta=null;foreach(['_bhc_tracking','_tracking_number','tracking_code','_wcdt_tracking','ywot_tracking_code'] as $meta_key){$value=sanitize_text_field((string)$order->get_meta($meta_key));if($value!==''){$tracking=$value;break;}}if($tracking===''){$ship=$order->get_meta('_wc_shipment_tracking_items');if(is_array($ship))foreach($ship as $row){if(is_array($row)&&!empty($row['tracking_number'])){$tracking=sanitize_text_field((string)$row['tracking_number']);$eta=!empty($row['date_shipped'])?sanitize_text_field((string)$row['date_shipped']):null;break;}}}
 wp_send_json_success(['order'=>['id'=>$order->get_id(),'status'=>$labels[$status]??'در حال بررسی','status_key'=>sanitize_key($status),'payment_state'=>$labels[$status]??'در حال بررسی','payment_method'=>sanitize_text_field($order->get_payment_method_title()?:'—'),'created'=>$order->get_date_created()?$order->get_date_created()->date_i18n('Y/m/d'):null,'items'=>count($lines),'lines'=>$lines,'tracking'=>$tracking!==''?$tracking:null,'shipped_on'=>$eta]]);
}
add_action('wp_ajax_bhc_order_lookup','bhc_order_lookup');
add_action('wp_ajax_nopriv_bhc_order_lookup','bhc_order_lookup');

add_action('init',function(){
 $next=wp_next_scheduled('bhc_privacy_cleanup');
 if($next&&$next>time()+5*MINUTE_IN_SECONDS){wp_unschedule_event($next,'bhc_privacy_cleanup');$next=false;}
 if(!$next)wp_schedule_event(time()+MINUTE_IN_SECONDS,'daily','bhc_privacy_cleanup');
});
function bhc_run_privacy_cleanup(){
 if(get_transient('bhc_privacy_cleanup_lock'))return;
 set_transient('bhc_privacy_cleanup_lock',1,10*MINUTE_IN_SECONDS);
 $ids=get_posts(['post_type'=>'bhc_lead','post_status'=>'private','posts_per_page'=>100,'fields'=>'ids','meta_query'=>[['key'=>'_bhc_privacy_expires','value'=>time(),'compare'=>'<','type'=>'NUMERIC']]]);
 foreach($ids as $id)wp_delete_post($id,true);
}
add_action('bhc_privacy_cleanup','bhc_run_privacy_cleanup');
add_action('init',function(){
 if(!get_transient('bhc_privacy_fallback_last')){bhc_run_privacy_cleanup();set_transient('bhc_privacy_fallback_last',1,6*HOUR_IN_SECONDS);}
},99);

add_action('wp_enqueue_scripts',function(){
