add_action('wp_enqueue_scripts',function(){
 wp_add_inline_script('bhc-chat',"document.addEventListener('DOMContentLoaded',function(){var w=document.querySelector('#bhc-widget'),b=w&&w.querySelector('.bhc-bot'),f=w&&w.querySelector('.bhc-form');if(!w||!f||typeof BHC==='undefined')return;var old=window.fetch;function notice(t){if(b)b.textContent=t;}function controls(){if(w.querySelector('.bhc-privacy-controls'))return;var d=document.createElement('div');d.className='bhc-privacy-controls';d.innerHTML='<span>کنترل داده‌های درخواست:</span> <button type=button data-privacy-export>دریافت داده</button> <button type=button data-privacy-delete>حذف داده</button>';w.append(d);d.querySelector('[data-privacy-export]').onclick=function(){var t=sessionStorage.getItem('bhc_privacy_token');if(!t)return notice('توکن حریم خصوصی در این مرورگر موجود نیست.');var x=new FormData();x.append('action','bhc_privacy_export');x.append('nonce',BHC.nonce);x.append('privacy_token',t);old(BHC.ajax,{method:'POST',body:x,credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){notice(j.success?'داده درخواست آماده دریافت است؛ اطلاعات تماس فقط با رضایت شما نمایش داده می‌شود.':(j.data&&j.data.message)||'دریافت داده انجام نشد.')}).catch(function(){notice('دریافت داده انجام نشد.')});};d.querySelector('[data-privacy-delete]').onclick=function(){var t=sessionStorage.getItem('bhc_privacy_token');if(!t)return notice('توکن حریم خصوصی در این مرورگر موجود نیست.');if(!confirm('درخواست و اطلاعات تماس حذف شود؟'))return;var x=new FormData();x.append('action','bhc_privacy_delete');x.append('nonce',BHC.nonce);x.append('privacy_token',t);old(BHC.ajax,{method:'POST',body:x,credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){if(j.success){sessionStorage.removeItem('bhc_privacy_token');d.remove();notice('درخواست و اطلاعات تماس حذف شد.');}else notice((j.data&&j.data.message)||'حذف داده انجام نشد.')}).catch(function(){notice('حذف داده انجام نشد.')});};}var original=window.fetch;window.fetch=function(input,init){var is