// Keep the custom management capability usable on existing installations as
// well as fresh ones. Administrators retain access through manage_options.
add_action('init',function(){
 if(get_option('bhc_capability_seed_v2')) return;
 foreach(['administrator','shop_manager'] as $role_name){
  $role=get_role($role_name);
  if($role){$role->add_cap('manage_baharan_commerce');foreach(['edit_bhc_leads','read_bhc_lead','read_private_bhc_leads','edit_private_bhc_leads','delete_bhc_leads','delete_private_bhc_leads'] as $cap)$role->add_cap($cap);}
 }
 update_option('bhc_capability_seed_v2',1,false);
});

add_filter('pre_update_option_bhc_options',function($value,$old){
 if(isset($_POST['bhc_options']['chat_avatar'])) $value['chat_avatar']=esc_url_raw(wp_unslash($_POST['bhc_options']['chat_avatar']));
 elseif(isset($old['chat_avatar'])) $value['chat_avatar']=$old['chat_avatar'];
 return $value;
},10,2);

